func parseConfiguration(_ config: String) -> [String: [String: String]] {
    var result: [String: [String: String]] = [:]

    let lines = config.components(separatedBy: .newlines)
    var currentSection: String?
    var currentSectionData: [String: String] = [:]

    for line in lines {
        if line.hasPrefix("// MARK: - ") {
            if let sectionName = line.components(separatedBy: " - ").last {
                currentSection = sectionName
                currentSectionData = [:]
            }
        } else if line == "// *******************" {
            if let section = currentSection {
                result[section] = currentSectionData
            }
        } else if let keyValuePair = line.components(separatedBy: ": ").map({ $0.trimmingCharacters(in: .whitespaces) }), keyValuePair.count == 2 {
            if let key = keyValuePair.first, let value = keyValuePair.last, let section = currentSection {
                currentSectionData[key] = value
            }
        }
    }

    return result
}

