func scalar<T>(at index: Int) throws -> T? {
    guard index >= 0 else {
        throw RetrievalError.invalidIndex
    }

    guard index < dataArray.count else {
        throw RetrievalError.indexOutOfBounds
    }

    do {
        let value = dataArray[index] as? T
        return value
    } catch {
        return nil
    }
}

