public class Logger {
    private let fileURL: URL

    /// Intializer.
    ///
    /// - Parameter fileURL: The file path to write the logs to.
    public init(fileURL: URL) {
        self.fileURL = fileURL
        if !FileManager.default.fileExists(atPath: fileURL.path) {
            if !FileManager.default.createFile(atPath: fileURL.path, contents: nil) {
                os_log("File for logging could not be created: %@", log: .default, type: .error, fileURL.path)
            }
        }
    }

    /// Write a log message to the file.
    ///
    /// - Parameter message: The message to be logged.
    public func log(message: String) {
        do {
            let fileHandle = try FileHandle(forWritingTo: fileURL)
            fileHandle.seekToEndOfFile()
            fileHandle.write(message.data(using: .utf8)!)
            fileHandle.closeFile()
        } catch {
            os_log("Failed to write to log file: %@", log: .default, type: .error, error.localizedDescription)
        }
    }
}

