func resolveDependencies(packageManifest: [String: Any]) -> [String] {
    var resolvedPackages: [String] = []
    var dependencyMap: [String: String] = [:]

    // Function to recursively resolve dependencies
    func resolvePackage(package: String) {
        if let dependency = dependencyMap[package] {
            resolvePackage(package: dependency)
        }
        resolvedPackages.append(package)
    }

    // Populate dependency map
    if let dependencies = packageManifest["dependencies"] as? [[String: String]] {
        for dependency in dependencies {
            if let name = dependency["name"], let version = dependency["version"] {
                dependencyMap[name] = version
            }
        }
    }

    // Resolve dependencies
    for (name, version) in dependencyMap {
        resolvePackage(package: name)
    }

    return resolvedPackages
}

