func generateMeme(topString: String, bottomString: String, originalImage: UIImage) -> Meme {
    let memeRect = CGRect(x: 0, y: 0, width: originalImage.size.width, height: originalImage.size.height)

    UIGraphicsBeginImageContextWithOptions(originalImage.size, false, 0.0)
    originalImage.draw(in: memeRect)

    let textAttributes: [NSAttributedString.Key: Any] = [
        .strokeColor: UIColor.black,
        .foregroundColor: UIColor.white,
        .font: UIFont(name: "HelveticaNeue-Bold", size: 40)!,
        .strokeWidth: -3.0
    ]

    let topTextRect = CGRect(x: 0, y: 20, width: originalImage.size.width, height: 100)
    let bottomTextRect = CGRect(x: 0, y: originalImage.size.height - 120, width: originalImage.size.width, height: 100)

    let topText = NSAttributedString(string: topString, attributes: textAttributes)
    let bottomText = NSAttributedString(string: bottomString, attributes: textAttributes)

    topText.draw(in: topTextRect)
    bottomText.draw(in: bottomTextRect)

    let memedImage = UIGraphicsGetImageFromCurrentImageContext()!
    UIGraphicsEndImageContext()

    return Meme(topString: topString, bottomString: bottomString, originalImage: originalImage, memedImage: memedImage)
}

