func calculateCRC(data: [UInt8]) -> UInt16 {
    var crc: UInt16 = 0x0000
    let polynomial: UInt16 = 0x1021

    for byte in data {
        crc = crc ^ (UInt16(byte) << 8)
        for _ in 0..<8 {
            if crc & 0x8000 != 0 {
                crc = (crc << 1) ^ polynomial
            } else {
                crc = crc << 1
            }
        }
    }
    return crc
}

