func constrainAspectRatio(to size: CGSize, relation: ConstraintRelation = .equal, isActive: Bool = true) -> NSLayoutConstraint {
    let aspectRatio = size.width / size.height
    let aspectRatioConstraint: NSLayoutConstraint

    switch relation {
        case .equal:
            aspectRatioConstraint = widthAnchor.constraint(equalTo: heightAnchor, multiplier: aspectRatio)
        case .greaterThanOrEqual:
            aspectRatioConstraint = widthAnchor.constraint(greaterThanOrEqualTo: heightAnchor, multiplier: aspectRatio)
        case .lessThanOrEqual:
            aspectRatioConstraint = widthAnchor.constraint(lessThanOrEqualTo: heightAnchor, multiplier: aspectRatio)
    }

    if isActive {
        aspectRatioConstraint.isActive = true
    }

    return aspectRatioConstraint
}

