func totalTrackDuration(sequencer: Sequencer, trackNumber: Int) -> AKDuration {
    guard trackNumber >= 0 && trackNumber < sequencer.tracks.count else {
        return AKDuration(beats: 0) // Return 0 duration for invalid track number
    }

    let track = sequencer.tracks[trackNumber]
    var totalDuration = AKDuration(beats: 0)

    for note in track.notes {
        let noteEnd = note.position.beats + note.duration.beats
        if noteEnd > totalDuration.beats {
            totalDuration = AKDuration(beats: noteEnd)
        }
    }

    return totalDuration
}

