func parsePackageManifest(_ content: String) -> [String: String] {
    var dependencies: [String: String] = [:]

    // Split the content by lines
    let lines = content.components(separatedBy: .newlines)

    // Regular expression pattern to match package URLs and version constraints
    let pattern = #"^\s*\.package\(url:\s*\"(https:\/\/[^"]+)\",\s*(.+)\)"#
    let regex = try! NSRegularExpression(pattern: pattern, options: [])

    for line in lines {
        if let match = regex.firstMatch(in: line, options: [], range: NSRange(location: 0, length: line.utf16.count)) {
            let urlRange = Range(match.range(at: 1), in: line)!
            let versionRange = Range(match.range(at: 2), in: line)!

            let url = String(line[urlRange])
            let versionConstraint = String(line[versionRange])

            dependencies[url] = versionConstraint
        }
    }

    return dependencies
}

