class QueueUsingStacks {
    var stack1: [Int] = []
    var stack2: [Int] = []

    func appendTail(_ value: Int) {
        // Push the element onto stack1
        stack1.append(value)
    }

    func deleteHead() -> Int {
        if stack2.isEmpty {
            // If stack2 is empty, transfer elements from stack1 to stack2
            while let element = stack1.popLast() {
                stack2.append(element)
            }
        }

