func garbageCollect(root: Object) {
    mark(root) // Mark all reachable objects starting from the root
    sweep()    // Sweep through the memory and deallocate unmarked objects
}

func mark(_ obj: Object) {
    if obj.marked {
        return
    }
    obj.marked = true
    for reference in obj.references {
        mark(reference) // Recursively mark referenced objects
    }
}

func sweep() {
    // Iterate through all allocated memory and deallocate unmarked objects
    for obj in allocatedMemory {
        if !obj.marked {
            deallocate(obj)
        } else {
            obj.marked = false // Reset the marked flag for the next garbage collection cycle
        }
    }
}

