func replaceRangeWithToken(attributedString: NSAttributedString, range: NSRange, token: String) -> NSAttributedString {
    // Get the attributes of the character after the specified range
    let attributes = attributedString.attributes(at: range.location + range.length - 1, effectiveRange: nil)

    // Create a mutable copy of the attributed substring within the specified range
    let mutableAttributedSubstring = attributedString.attributedSubstring(from: range).mutableCopy() as! NSMutableAttributedString

    // Replace the content of the mutable attributed substring with the token string
    mutableAttributedSubstring.mutableString.setString(token)

    // Apply the original attributes to the token string
    mutableAttributedSubstring.addAttributes(attributes, range: NSRange(location: 0, length: mutableAttributedSubstring.length))

    // Create a mutable copy of the original attributed string
    let mutableAttributedString = NSMutableAttributedString(attributedString: attributedString)

    // Replace the specified range with the modified attributed substring
    mutableAttributedString.replaceCharacters(in: range, with: mutableAttributedSubstring)

    // Return the new attributed string with the replaced range
    return NSAttributedString(attributedString: mutableAttributedString)
}

