import Metal

func elementwiseAddUsingMetal(_ array1: [Int], _ array2: [Int], axis: Int) -> [Int] {
    // Create a Metal device and command queue
    guard let device = MTLCreateSystemDefaultDevice(),
          let commandQueue = device.makeCommandQueue() else {
        fatalError("Metal is not supported on this device")
    }

    // Create a Metal buffer for array1 and array2
    let buffer1 = device.makeBuffer(bytes: array1, length: array1.count * MemoryLayout<Int>.stride, options: [])
    let buffer2 = device.makeBuffer(bytes: array2, length: array2.count * MemoryLayout<Int>.stride, options: [])

    // Create a Metal compute function for element-wise addition
    let defaultLibrary = device.makeDefaultLibrary()
    let kernelFunction = defaultLibrary?.makeFunction(name: "elementwiseAdd")

    // Create a Metal compute pipeline
    do {
        let computePipeline = try device.makeComputePipelineState(function: kernelFunction!)

        // Create a Metal command buffer and encoder
        guard let commandBuffer = commandQueue.makeCommandBuffer(),
              let computeCommandEncoder = commandBuffer.makeComputeCommandEncoder() else {
            fatalError("Failed to create Metal command buffer or encoder")
        }

        // Set the compute pipeline state and buffers
        computeCommandEncoder.setComputePipelineState(computePipeline)
        computeCommandEncoder.setBuffer(buffer1, offset: 0, index: 0)
        computeCommandEncoder.setBuffer(buffer2, offset: 0, index: 1)

        // Calculate the threadgroup size and dispatch the compute kernel
        let threadgroupSize = MTLSize(width: 1, height: 1, depth: 1)
        let threadgroupCount = MTLSize(width: array1.count, height: 1, depth: 1)
        computeCommandEncoder.dispatchThreadgroups(threadgroupCount, threadsPerThreadgroup: threadgroupSize)

        // End the encoding and commit the command buffer
        computeCommandEncoder.endEncoding()
        commandBuffer.commit()
        commandBuffer.waitUntilCompleted()

        // Retrieve the result from the buffer
        var result = [Int](repeating: 0, count: array1.count)
        let contents = buffer1?.contents().bindMemory(to: Int.self, capacity: array1.count)
        for i in 0..<array1.count {
            result[i] = contents![i]
        }

        return result
    } catch {
        fatalError("Failed to create compute pipeline")
    }
}

