    let executionTime: Date
}

class TaskScheduler {
    private var scheduledTasks: [Int: Date] = [:]

    func scheduleTask(taskId: Int, executionTime: Date) {
        scheduledTasks[taskId] = executionTime
    }

    func unscheduleTask(taskId: Int) {
        scheduledTasks.removeValue(forKey: taskId)
    }

    func executeDueTasks(currentTime: Date) -> [Int] {
        var dueTasks: [Int] = []
        for (taskId, executionTime) in scheduledTasks {
            if executionTime <= currentTime {
                dueTasks.append(taskId)
            }
        }
        dueTasks.forEach { taskId in
            scheduledTasks.removeValue(forKey: taskId)
        }
        return dueTasks
    }
}

