func isVideoCached(url: String) -> Bool {
    let videoFileName = (url as NSString).lastPathComponent
    let videoFilePath = (VideoCacheSettings.kCachePath as String).appendingPathComponent(videoFileName)

    let fileManager = FileManager.default
    var isDirectory: ObjCBool = false

    if fileManager.fileExists(atPath: videoFilePath, isDirectory: &isDirectory) {
        if !isDirectory.boolValue {
            do {
                let attributes = try fileManager.attributesOfItem(atPath: videoFilePath)
                if let modificationDate = attributes[.modificationDate] as? Date {
                    let ageInSeconds = -modificationDate.timeIntervalSinceNow
                    if ageInSeconds <= Double(VideoCacheSettings.kMCacheAge) {
                        return true
                    }
                }
            } catch {
                // Handle file attributes retrieval error
            }
        }
    }

    return false
}

