class TaskScheduler {
    private var tasks: [String: Int] = [:] // Dictionary to store task name and remaining duration

    // Add task to the scheduler
    func addTask(name: String, duration: Int) {
        tasks[name] = duration
    }

    // Pause a running task
    func pauseTask(name: String) {
        if let remainingDuration = tasks[name] {
            tasks[name] = remainingDuration
        }
    }

    // Resume a paused task
    func resumeTask(name: String) {
        if let remainingDuration = tasks[name] {
            tasks[name] = remainingDuration
        }
    }

    // Handle application entering background state
    func handleBackground() {
        for (name, remainingDuration) in tasks {
            tasks[name] = remainingDuration
        }
    }

    // Handle application becoming active
    func handleActive() {
        for (name, remainingDuration) in tasks {
            tasks[name] = remainingDuration
        }
    }
}

