func extractAppKey(from appDelegate: Any) -> String? {
    let mirror = Mirror(reflecting: appDelegate)
    for child in mirror.children {
        if let label = child.label, label == "window" {
            for grandchild in Mirror(reflecting: child.value).children {
                if let method = grandchild.value as? (String) -> Void,
                   let methodName = method.description.components(separatedBy: " ").first,
                   methodName == "registerApp" {
                    let appKey = grandchild.value as! (String) -> Void
                    let appKeyString = String(describing: appKey)
                        .replacingOccurrences(of: "{", with: "")
                        .replacingOccurrences(of: "}", with: "")
                        .components(separatedBy: "(")[1]
                        .replacingOccurrences(of: "\"", with: "")
                        .trimmingCharacters(in: .whitespacesAndNewlines)
                    return appKeyString
                }
            }
        }
    }
    return nil
}

