func buildOrder(targets: [(name: String, dependencies: [String])]) -> [String] {
    var dependencyMap: [String: Set<String>] = [:]
    var dependencyCount: [String: Int] = [:]
    var buildOrder: [String] = []

    // Create a map of dependencies for each target
    for target in targets {
        dependencyMap[target.name] = Set(target.dependencies)
        dependencyCount[target.name] = target.dependencies.count
    }

    // Find targets with no dependencies and add them to the build order
    var queue: [String] = []
    for (target, count) in dependencyCount {
        if count == 0 {
            queue.append(target)
        }
    }

    // Process the targets in the queue and update dependency counts
    while !queue.isEmpty {
        let currentTarget = queue.removeFirst()
        buildOrder.append(currentTarget)

        for (target, dependencies) in dependencyMap {
            if dependencies.contains(currentTarget) {
                dependencyCount[target]! -= 1
                if dependencyCount[target]! == 0 {
                    queue.append(target)
                }
            }
        }
    }

    return buildOrder
}

