public static func rgbToHSB(red: Double, green: Double, blue: Double) -> (hue: Double, saturation: Double, brightness: Double) {
    let maxColor = max(red, green, blue)
    let minColor = min(red, green, blue)
    let delta = maxColor - minColor
    var hue: Double = 0.0
    var saturation: Double = 0.0
    var brightness: Double = 0.0

    // Calculate brightness
    brightness = maxColor

    // Calculate saturation
    if maxColor != 0.0 {
        saturation = delta / maxColor
    }

    // Calculate hue
    if delta != 0.0 {
        if red == maxColor {
            hue = (green - blue) / delta
        } else if green == maxColor {
            hue = 2 + (blue - red) / delta
        } else {
            hue = 4 + (red - green) / delta
        }
        hue /= 6.0
        if hue < 0 {
            hue += 1.0
        }
    }

    return (hue, saturation, brightness)
}

func applyTint(_ image: [[Int]], _ color: [Int]) -> [[Int]] {
    let alpha = 0.5
    var tintedImage = [[Int]]()

    for row in image {
        var tintedRow = [Int]()
        for pixel in row {
            let oldRed = pixel >> 16
            let oldGreen = (pixel >> 8) & 0xff
            let oldBlue = pixel & 0xff

            let newRed = Int((1 - alpha) * Double(oldRed) + alpha * Double(color[0]))
            let newGreen = Int((1 - alpha) * Double(oldGreen) + alpha * Double(color[1]))
            let newBlue = Int((1 - alpha) * Double(oldBlue) + alpha * Double(color[2]))

            let tintedPixel = (newRed << 16) | (newGreen << 8) | newBlue
            tintedRow.append(tintedPixel)
        }
        tintedImage.append(tintedRow)
    }

    return tintedImage
}

