code:
import UIKit

class TaskScheduler {
    private var scheduledTasks: [(DispatchWorkItem, TimeInterval)] = []
    private var isApplicationActive = true

    init() {
        NotificationCenter.default.addObserver(self, selector: #selector(applicationWillEnterForeground), name: UIApplication.willEnterForegroundNotification, object: nil)
        NotificationCenter.default.addObserver(self, selector: #selector(applicationDidBecomeActive), name: UIApplication.didBecomeActiveNotification, object: nil)
    }

    deinit {
        NotificationCenter.default.removeObserver(self)
    }

    @objc private func applicationWillEnterForeground() {
        isApplicationActive = false
    }

    @objc private func applicationDidBecomeActive() {
        isApplicationActive = true
        executeScheduledTasks()
    }

    private func executeScheduledTasks() {
        for (task, delay) in scheduledTasks {
            if isApplicationActive {
                DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: task)
            } else {
                task.perform()
            }
        }
        scheduledTasks.removeAll()
    }

    func scheduleTask(_ task: @escaping () -> Void, delay: TimeInterval) {
        let workItem = DispatchWorkItem(block: task)
        if isApplicationActive {
            DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: workItem)
        } else {
            scheduledTasks.append((workItem, delay))
        }
    }
}

