    if !fileManager.fileExists(atPath: sourceDirectory, isDirectory: &isDirectory) {
        // Create the source directory if it does not exist
        try? fileManager.createDirectory(atPath: sourceDirectory, withIntermediateDirectories: true, attributes: nil)
    }

