func adjustPosition(currentPosition: CGPoint, visibleRect: CGRect) -> CGPoint {
    var newCenter = currentPosition
    if newCenter.x < visibleRect.minX {
        newCenter.x = visibleRect.minX
    } else if newCenter.x > visibleRect.maxX {
        newCenter.x = visibleRect.maxX
    }
    if newCenter.y < visibleRect.minY {
