public struct AsyncPrefixWhileSequence<Base: AsyncSequence> {
  @usableFromInline
  let base: Base

  @usableFromInline
  let predicate: (Base.Element) async -> Bool

  @usableFromInline
  init(base: Base, predicate: @escaping (Base.Element) async -> Bool) {
    self.base = base
    self.predicate = predicate
  }
}

extension AsyncPrefixWhileSequence: AsyncSequence {
  public struct AsyncIterator: AsyncIteratorProtocol {
    public mutating func next() async throws -> Base.Element? {
      while let element = try await base.next() {
        if await predicate(element) {
          return element
        }
      }
      return nil
    }
  }

  public func makeAsyncIterator() -> AsyncIterator {
    return AsyncIterator()
  }
}

