import Foundation

class ThreadSafeStorage {
    private let lck = SDConditionLock()
    private var storage = Atomic<Result?>(value: nil)
    private let queue: DispatchQueue

    private init(queue: DispatchQueue) {
        self.queue = queue
    }

    func setResult(result: Result) {
        queue.async {
            self.storage.mutate { currentResult in
                self.storage.value = result
                self.lck.signal()
            }
        }
    }

    func getResult() -> Result? {
        var result: Result?
        lck.lock()
        while storage.value == nil {
            lck.wait()
        }
        result = storage.value
        lck.unlock()
        return result
    }
}

