func applyGrayscaleFilter(to image: UIImage) -> UIImage {
    // Create a graphics context with the same size as the image
    UIGraphicsBeginImageContextWithOptions(image.size, false, 1.0)
    let context = UIGraphicsGetCurrentContext()

    // Draw the image into the context
    image.draw(in: CGRect(x: 0, y: 0, width: image.size.width, height: image.size.height))

    // Get the image data
    guard let cgImage = context?.makeImage() else {
        return UIImage()
    }

    // Convert the image to grayscale
    guard let grayscaleContext = CGContext(data: nil, width: cgImage.width, height: cgImage.height, bitsPerComponent: 8, bytesPerRow: cgImage.width * 4, space: CGColorSpaceCreateDeviceGray(), bitmapInfo: CGImageAlphaInfo.none.rawValue) else {
        return UIImage()
    }

    grayscaleContext.draw(cgImage, in: CGRect(x: 0, y: 0, width: cgImage.width, height: cgImage.height))

    // Create a new grayscale image
    guard let grayscaleCGImage = grayscaleContext.makeImage() else {
        return UIImage()
    }

    // Convert the grayscale image back to a UIImage
    let grayscaleImage = UIImage(cgImage: grayscaleCGImage)

    // End the graphics context
    UIGraphicsEndImageContext()

    return grayscaleImage
}

