class GPXParser {
    // MARK:- GPX
    func addChildTag(toGPX gpx: NSMutableString, indentationLevel: Int) {
        let indentation = String(repeating: " ", count: indentationLevel * 4)
        gpx.append("\(indentation)<childTag>\n")
        gpx.append("\(indentation)    <subTag1>value1</subTag1>\n")
        gpx.append("\(indentation)    <subTag2>value2</subTag2>\n")
        gpx.append("\(indentation)</childTag>\n")
    }
}

