import NAPI

func convertToJSArray(_ env: napi_env, _ inputArray: [Int]) throws -> napi_value {
    var result: napi_value?

    let status = napi_create_array_with_length(env, inputArray.count, &result)
    guard status == napi_ok else { throw NAPI.Error(status) }

    for (index, element) in inputArray.enumerated() {
        let jsValue = try element.napiValue(env)
        let status = napi_set_element(env, result!, index, jsValue)
        guard status == napi_ok else { throw NAPI.Error(status) }
    }

    return result!
}

