import Foundation
import Realm
import RealmSwift

class InventoryItem: Object {
    @objc dynamic var id = UUID().uuidString
    @objc dynamic var name = ""
    @objc dynamic var quantity = 0
    @objc dynamic var price = 0.0
}

let realm = try! Realm()

func addItem(name: String, quantity: Int, price: Double) {
    let newItem = InventoryItem()
    newItem.name = name
    newItem.quantity = quantity
    newItem.price = price

    try! realm.write {
        realm.add(newItem)
    }
}

func updateItem(id: String, quantity: Int, price: Double) {
    if let item = realm.object(ofType: InventoryItem.self, forPrimaryKey: id) {
        try! realm.write {
            item.quantity = quantity
            item.price = price
        }
    }
}

func getItemById(id: String) -> InventoryItem? {
    return realm.object(ofType: InventoryItem.self, forPrimaryKey: id)
}

func processMentions(in text: String, removeEntireMention: Bool) -> String {
    var processedText = text
    let mentionRegex = try! NSRegularExpression(pattern: "@\\w+", options: [])
    let matches = mentionRegex.matches(in: text, options: [], range: NSRange(location: 0, length: text.utf16.count))

    for match in matches.reversed() {
        let mentionRange = Range(match.range, in: text)!
        if removeEntireMention {
            processedText.removeSubrange(mentionRange)
        } else {
            let usernameRange = Range(NSRange(location: mentionRange.lowerBound + 1, length: mentionRange.upperBound - mentionRange.lowerBound - 1), in: text)!
            processedText.replaceSubrange(usernameRange, with: "")
        }
    }

    return processedText
}

