import SpriteKit

class GameScene: SKScene {

    var spaceship: SKSpriteNode!
    var isMoving: Bool = true

    override func didMove(to view: SKView) {
        // Create and configure the spaceship
        spaceship = SKSpriteNode(imageNamed: "spaceship")
        spaceship.position = CGPoint(x: size.width / 2, y: size.height / 2)
        addChild(spaceship)

        // Start moving the spaceship
        run(moveShip)

        // Add tap gesture recognizer
        let tapGesture = UITapGestureRecognizer(target: self, action: #selector(handleTap(_:)))
        view.addGestureRecognizer(tapGesture)
    }

    func moveShip() {
        let moveAction = SKAction.move(by: CGVector(dx: 100, dy: 0), duration: 1)
        spaceship.run(SKAction.repeatForever(moveAction), withKey: "moveAction")
    }

    @objc func handleTap(_ sender: UITapGestureRecognizer) {
        if isMoving {
            spaceship.removeAction(forKey: "moveAction")
            stopMove()
            isMoving = false
        }
    }

    func stopMove() {
        let delay: TimeInterval = 1
        let stop: SKAction = SKAction.run {
            self.spaceship.physicsBody?.velocity = CGVector(dx: 0, dy: 0)
        }
        let wait = SKAction.wait(forDuration: delay)
        let stopping = SKAction.sequence([wait, stop])
        spaceship.run(stopping, withKey: "stopAction")
    }
}

