enum HTTPServerResponsePart {
    case body(ByteBuffer)
    case end(ByteBuffer?)
}

class Delegate {
    var reads: Int = 0
    var promise: EventLoopPromise<Void>

    init(promise: EventLoopPromise<Void>) {
        self.promise = promise
    }
}

func processHTTPResponse(responsePart: HTTPServerResponsePart, buffer: ByteBuffer?, delegate: Delegate, channel: Channel, future: EventLoopFuture<Void>) throws {
    switch responsePart {
    case .body(let byteBuffer):
        try channel.writeAndFlush(HTTPServerResponsePart.body(byteBuffer)).wait()
        delegate.reads += 1
    case .end(_):
        try channel.writeAndFlush(HTTPServerResponsePart.end(nil)).wait()
        try future.wait()
        delegate.reads += 2
    }
}

