class BankingSystem {
    var accounts: [BankAccount] = []

    // Add a new account with a unique account number and initial balance
    func createAccount(accountNumber: Int, initialBalance: Double) {
        guard !accounts.contains(where: { $0.accountNumber == accountNumber }) else {
            print("Account with the same number already exists.")
            return
        }
        let newAccount = BankAccount(accountNumber: accountNumber, balance: initialBalance)
        accounts.append(newAccount)
    }

    // Deposit funds into the specified account
    func depositFunds(accountNumber: Int, amount: Double) {
        guard let accountIndex = accounts.firstIndex(where: { $0.accountNumber == accountNumber }) else {
            print("Account not found.")
            return
        }
        accounts[accountIndex].balance += amount
    }

    // Withdraw funds from the specified account
    func withdrawFunds(accountNumber: Int, amount: Double) {
        guard let accountIndex = accounts.firstIndex(where: { $0.accountNumber == accountNumber }) else {
            print("Account not found.")
            return
        }
        guard accounts[accountIndex].balance >= amount else {
            print("Insufficient funds.")
            return
        }
        accounts[accountIndex].balance -= amount
    }

    // Transfer funds from one account to another
    func transferFunds(fromAccount: Int, toAccount: Int, amount: Double) {
        guard let fromIndex = accounts.firstIndex(where: { $0.accountNumber == fromAccount }),
              let toIndex = accounts.firstIndex(where: { $0.accountNumber == toAccount }) else {
            print("One or both accounts not found.")
            return
        }
        guard accounts[fromIndex].balance >= amount else {
            print("Insufficient funds for transfer.")
            return
        }
        accounts[fromIndex].balance -= amount
        accounts[toIndex].balance += amount
    }

    // Retrieve the account information for the specified account number
    func getAccountInfo(accountNumber: Int) -> BankAccount? {
        return accounts.first(where: { $0.accountNumber == accountNumber })
    }

    // Retrieve the account balance for the specified account number
    func getAccountBalance(accountNumber: Int) -> Double? {
        return accounts.first(where: { $0.accountNumber == accountNumber })?.balance
    }
}

