code:
import UIKit

class TaskScheduler {
    private var scheduledTasks: [DispatchWorkItem] = []

    func scheduleTask(task: @escaping () -> Void, delay: TimeInterval) {
        let workItem = DispatchWorkItem {
            task()
        }
        scheduledTasks.append(workItem)
        DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: workItem)
    }

    func cancelTask(task: @escaping () -> Void) {
        if let index = scheduledTasks.firstIndex(where: { $0.perform == task }) {
            scheduledTasks[index].cancel()
            scheduledTasks.remove(at: index)
        }
    }

    func sceneDidBecomeActive(_ scene: UIScene) {
        // Execute scheduled tasks that have reached their execution time
        for (index, workItem) in scheduledTasks.enumerated() {
            if !workItem.isCancelled {
                workItem.perform()
                scheduledTasks.remove(at: index)
            }
        }
    }

    func sceneWillResignActive(_ scene: UIScene) {
        // Cancel any remaining scheduled tasks
        for workItem in scheduledTasks {
            workItem.cancel()
        }
        scheduledTasks.removeAll()
    }
}

