func parseFilePath(_ filePath: String) -> [String: String] {
    var fileInfo: [String: String] = [:]

    let components = filePath.components(separatedBy: "/")
    if components.count >= 2 {
        let path = components.dropLast().joined(separator: "/")
        let fileWithExtension = components.last!

        if let range = fileWithExtension.range(of: ".") {
            let filename = String(fileWithExtension.prefix(upTo: range.lowerBound))
            let extensionType = String(fileWithExtension.suffix(from: range.upperBound))

            fileInfo["path"] = path
            fileInfo["filename"] = filename
            fileInfo["extension"] = extensionType
        }
    }

    return fileInfo
}

