        let key = components[0]
        let value = components[1]

        if dict[key] != nil {
            dict[key]!.append(value)
        } else {
            dict[key] = [value]
        }
    }

    let keys = Array(dict.keys)
    var temp: [[String]] = []
    for key in keys {
        temp.append(dict[key]!)
    }
    return temp
}

