        storage = Array(repeating: nil, count: size)
    }

    mutating func write(data: T) {
        if storage[writeIndex] != nil {
            readIndex = (readIndex + 1) % storage.count
        }
        storage[writeIndex] = data
        writeIndex = (writeIndex + 1) % storage.count
    }

    mutating func read() -> T? {
        guard let data = storage[readIndex] else { return nil }
        storage[readIndex] = nil
        readIndex = (readIndex + 1) % storage.count
        return data
    }

    mutating func clear() {
        storage = Array(repeating: nil, count: storage.count)
        readIndex = 0
        writeIndex = 0
    }
}

