import MetalKit

class MetalShaderRunner {
    var device: MTLDevice!
    var library: MTLLibrary!
    var commandQueue: MTLCommandQueue!
    var pipelineState: MTLComputePipelineState!

    func loadShaderFromFile(filePath: String) {
        guard let device = MTLCreateSystemDefaultDevice() else {
            fatalError("Metal is not supported on this device")
        }
        self.device = device

        do {
            let library = try device.makeLibrary(filepath: filePath)
            self.library = library
        } catch {
            fatalError("Failed to load shader from file: \(error)")
        }
    }

    func compileShader() {
        guard let function = library.makeFunction(name: "computeShaderFunction") else {
            fatalError("Failed to find compute function in the shader")
        }

        do {
            let pipelineState = try device.makeComputePipelineState(function: function)
            self.pipelineState = pipelineState
        } catch {
            fatalError("Failed to create pipeline state: \(error)")
        }
    }

    func executeShader(inputData: [Float]) -> [Float] {
        guard let commandBuffer = commandQueue.makeCommandBuffer() else {
            fatalError("Failed to create command buffer")
        }

        guard let inputBuffer = device.makeBuffer(bytes: inputData, length: inputData.count * MemoryLayout<Float>.stride, options: []) else {
            fatalError("Failed to create input buffer")
        }

        guard let outputBuffer = device.makeBuffer(length: inputData.count * MemoryLayout<Float>.stride, options: []) else {
            fatalError("Failed to create output buffer")
        }

        let computeCommandEncoder = commandBuffer.makeComputeCommandEncoder()
        computeCommandEncoder.setComputePipelineState(pipelineState)
        computeCommandEncoder.setBuffer(inputBuffer, offset: 0, index: 0)
        computeCommandEncoder.setBuffer(outputBuffer, offset: 0, index: 1)

        let threadsPerThreadgroup = MTLSize(width: inputData.count, height: 1, depth: 1)
        let threadgroupsPerGrid = MTLSize(width: 1, height: 1, depth: 1)
        computeCommandEncoder.dispatchThreadgroups(threadgroupsPerGrid, threadsPerThreadgroup: threadsPerThreadgroup)
        computeCommandEncoder.endEncoding()

        commandBuffer.commit()
        commandBuffer.waitUntilCompleted()

        let outputData = Array(UnsafeBufferPointer(start: outputBuffer.contents().assumingMemoryBound(to: Float.self), count: inputData.count))
        return outputData
    }

    init() {
        guard let device = MTLCreateSystemDefaultDevice() else {
            fatalError("Metal is not supported on this device")
        }
        self.device = device
        self.library = device.makeDefaultLibrary()
        self.commandQueue = device.makeCommandQueue()
    }
}

