func calculateTotalSpaceOccupied(by stackView: UIStackView) -> CGFloat {
    var totalSpace: CGFloat = 0

    // Calculate the total space occupied by the arranged subviews
    for subview in stackView.arrangedSubviews {
        if stackView.axis == .vertical {
            totalSpace += subview.frame.height
        } else {
            totalSpace += subview.frame.width
        }
    }

    // Add the layout margins to the total space
    if stackView.axis == .vertical {
        totalSpace += stackView.layoutMargins.top + stackView.layoutMargins.bottom
    } else {
        totalSpace += stackView.layoutMargins.left + stackView.layoutMargins.right
    }

    return totalSpace
}

