        return nil
    }

    // Set the client format to the output format
    err = ExtAudioFileSetProperty(externalAudioFileRef, kExtAudioFileProperty_ClientDataFormat, UInt32(MemoryLayout.stride(ofValue: theOutputFormat)), &theOutputFormat)
    if err != 0 { Log("ExtAudioFileSetProperty FAILED, Error = \(err)"); return nil }

    // Get the audio file length in frames
