    err = ExtAudioFileGetProperty(externalAudioFileRef, kExtAudioFileProperty_FileLengthFrames, &thePropertySize, &theFileLengthInFrames)
    if err != 0 { Log("ExtAudioFileGetProperty FAILED, Error = \(err)"); return nil }

    // Allocate memory for the audio data
    let dataSize = UInt32(theFileLengthInFrames) * theOutputFormat.mBytesPerFrame
    theData = UnsafeMutablePointer<CChar>.allocate(capacity: Int(dataSize))

    // Read the audio data
    var ioNumBytes: UInt32 = dataSize
    err = ExtAudioFileRead(externalAudioFileRef, &ioNumBytes, theData)
    if err != 0 { Log("ExtAudioFileRead FAILED, Error = \(err)"); return nil }

    // Close the audio file
    err = ExtAudioFileDispose(externalAudioFileRef)
    if err != 0 { Log("ExtAudioFileDispose FAILED, Error = \(err)"); return nil }

    return theData
}

