func findCircularDependencies(_ dependencies: [String: [String]]) -> [[String]] {
    var visited = Set<String>()
    var inProgress = Set<String>()
    var circularDeps: [[String]] = []

    func dfs(_ package: String, _ path: [String]) {
        visited.insert(package)
        inProgress.insert(package)

        for dep in dependencies[package, default: []] {
            if inProgress.contains(dep) {
                let cycleStartIndex = path.firstIndex(of: dep)!
                circularDeps.append(Array(path[cycleStartIndex...]))
            } else if !visited.contains(dep) {
                dfs(dep, path + [dep])
            }
        }

        inProgress.remove(package)
    }

    for package in dependencies.keys {
        if !visited.contains(package) {
            dfs(package, [package])
        }
    }

    return circularDeps
}

