import Foundation

class ConcurrentSet<T: Hashable> {
    private var entries = [T]()
    private let queue = DispatchQueue(label: "com.example.ConcurrentSetQueue")

    func add(_ element: T) {
        queue.async(flags: .barrier) {
            self.entries.append(element)
        }
    }

    func remove(_ element: T) {
        queue.async(flags: .barrier) {
            if let index = self.entries.firstIndex(of: element) {
                self.entries.remove(at: index)
            }
        }
    }

    func contains(_ element: T) -> Bool {
        var containsElement = false
        queue.sync {
            containsElement = self.entries.contains(element)
        }
        return containsElement
    }

    func removeAll() {
        queue.async(flags: .barrier) {
            self.entries.removeAll()
        }
    }
}

