import CoreGraphics

func convertMTLTextureToCGImage(
    _ texture: MTLTexture,
    completionBlock: (CGImage) -> Void
) -> CGImage {
    let bytesPerPixel: Int = 4
    let bytesPerRow: Int = bytesPerPixel * texture.width
    let byteCount: Int = bytesPerRow * texture.height

    var pixelData = [UInt8](repeating: 0, count: byteCount)
    let region = MTLRegionMake2D(0, 0, texture.width, texture.height)
    texture.getBytes(&pixelData, bytesPerRow: bytesPerRow, from: region, mipmapLevel: 0)

    let colorSpace = CGColorSpaceCreateDeviceRGB()
    let bitmapInfo: CGBitmapInfo = [.byteOrder32Big, CGBitmapInfo(rawValue: CGImageAlphaInfo.premultipliedLast.rawValue)]
    let context = CGContext(
        data: &pixelData,
        width: texture.width,
        height: texture.height,
        bitsPerComponent: 8,
        bytesPerRow: bytesPerRow,
        space: colorSpace,
        bitmapInfo: bitmapInfo.rawValue
    )

    guard let cgImage = context?.makeImage() else {
        fatalError("Failed to create CGImage from MTLTexture")
    }

    completionBlock(cgImage)
    return cgImage
}

