class LRUCache {
    class Node {
        let key: Int
        var value: Int
        var prev: Node?
        var next: Node?

        init(_ key: Int, _ value: Int) {
            self.key = key
            self.value = value
        }
    }

    var capacity: Int
    var cache: [Int: Node]
    var head: Node
    var tail: Node

    init(_ capacity: Int) {
        self.capacity = capacity
        self.cache = [:]
        self.head = Node(-1, -1)
        self.tail = Node(-1, -1)
        self.head.next = self.tail
        self.tail.prev = self.head
    }

    func removeNode(_ node: Node) {
        node.prev?.next = node.next
        node.next?.prev = node.prev
    }

    func addToHead(_ node: Node) {
        node.next = head.next
        node.prev = head
        head.next?.prev = node
        head.next = node
    }

    func get(_ key: Int) -> Int {
        if let node = cache[key] {
            removeNode(node)
            addToHead(node)
            return node.value
        }
        return -1
    }

    func put(_ key: Int, _ value: Int) {
        if let node = cache[key] {
            node.value = value
            removeNode(node)
            addToHead(node)
        } else {
            let newNode = Node(key, value)
            cache[key] = newNode
            addToHead(newNode)
            if cache.count > capacity {
                if let tailPrev = tail.prev {
                    removeNode(tailPrev)
                    cache[tailPrev.key] = nil
                }
            }
        }
    }
}

