func isValidPawnMove(move: Move) -> Bool {
    let fileDifference = abs(move.destination.file.rawValue - move.origin.file.rawValue)
    let rankDifference = move.destination.rank.rawValue - move.origin.rank.rawValue

    // Pawn moves forward one square
    if fileDifference == 0 && rankDifference == 1 {
        return true
    }

    // Pawn moves forward two squares on its first move
    if fileDifference == 0 && rankDifference == 2 && move.origin.rank == .two {
        return true
    }

    // Pawn captures diagonally
    if fileDifference == 1 && rankDifference == 1 && move.capturedPiece != nil {
        return true
    }

    return false
