func encodeChars(_ bytes: [Int8]) -> String {
    var result = ""
    var prevChar: Character = " "

    for byte in bytes {
        if byte > 0 {
            let char = Character(UnicodeScalar(UInt8(bitPattern: byte)))
            result.append(char)
            prevChar = char
        } else {
            let repeatCount = Int(abs(byte))
            if repeatCount > 0 {
                result.append(String(repeating: prevChar, count: repeatCount))
            }
        }
    }

