func localizeDate(date: Date, option: DateOption) -> String {
    let dateFormater = DateFormatter()
    dateFormater.dateFormat = "yyyy-MM-dd"

    let weekdayFormater = DateFormatter()
    weekdayFormater.dateFormat = "EEEE"

    switch option {
    case .today:
        return l("date_today", dateFormater.string(from: date))
    case .yesterday:
        let yesterday = Calendar.current.date(byAdding: .day, value: -1, to: date)!
        return l("date_yesterday", dateFormater.string(from: yesterday))
    case .tomorrow:
        let tomorrow = Calendar.current.date(byAdding: .day, value: 1, to: date)!
        return l("date_tomorrow", dateFormater.string(from: tomorrow))
    case .thisWeek:
        return l("date_this", weekdayFormater.string(from: date), dateFormater.string(from: date))
    case .lastWeek:
        let lastWeek = Calendar.current.date(byAdding: .weekOfYear, value: -1, to: date)!
        return l("date_last", weekdayFormater.string(from: lastWeek), dateFormater.string(from: lastWeek))
    case .nextWeek:
        let nextWeek = Calendar.current.date(byAdding: .weekOfYear, value: 1, to: date)!
        return l("date_next", weekdayFormater.string(from: nextWeek), dateFormater.string(from: nextWeek))
    }
}

