func minJumps(_ nums: [Int]) -> Int {
    guard nums.count > 0 else {
        return -1 // Invalid length
    }

    guard nums.filter({ $0 > 0 }).count > 0 else {
        return -1 // All inputs must be positive
    }

    var jumps = 0
    var currentEnd = 0
    var farthest = 0

    for i in 0..<nums.count - 1 {
        farthest = max(farthest, i + nums[i])

        if i == currentEnd {
            jumps += 1
            currentEnd = farthest
        }
    }

    return currentEnd >= nums.count - 1 ? jumps : -1
}

class MemoryManager {
    var totalMemory: Int
    var usedMemory: Int
    var memoryQueue: [Int]

    init(totalMemory: Int) {
        self.totalMemory = totalMemory
        self.usedMemory = 0
        self.memoryQueue = []
    }

    func allocateMemory(_ memory: Int) {
        if usedMemory + memory <= totalMemory {
            usedMemory += memory
            memoryQueue.append(memory)
        } else {
            print("Memory allocation failed: Insufficient memory")
        }
    }

    func releaseMemory(_ memory: Int) {
        while memory > 0 && !memoryQueue.isEmpty {
            let releasedMemory = memoryQueue.removeFirst()
            if releasedMemory <= memory {
                memory -= releasedMemory
                usedMemory -= releasedMemory
            } else {
                memoryQueue.insert(releasedMemory - memory, at: 0)
                usedMemory -= memory
                memory = 0
            }
        }
        if memory > 0 {
            print("Memory release failed: Insufficient memory to release")
        }
    }
}

