func convertToMultipartString(parameters: [MultipartParameter], boundary: String) -> String {
    var multipartString = ""

    for parameter in parameters {
        multipartString += "--\(boundary)\r\n"
        multipartString += "Content-Disposition: form-data; name=\"\(parameter.name)\"\r\n\r\n"
        if let parameterString = String(data: parameter.data, encoding: .utf8) {
            multipartString += "\(parameterString)\r\n"
        }
    }

    multipartString += "--\(boundary)--"

    return multipartString
}

