class Observer {
    var subscribers: [String: [() -> Void]] = [:]

    func observe(flow: String, subscriber: @escaping () -> Void) {
        if subscribers[flow] != nil {
            subscribers[flow]?.append(subscriber)
        } else {
            subscribers[flow] = [subscriber]
        }
    }

    func notify(flow: String) {
        if let flowSubscribers = subscribers[flow] {
            for subscriber in flowSubscribers {
                subscriber()
            }
        }
    }
}

