class HTTPRequestHandler: ChannelInboundHandler {
    typealias InboundIn = HTTPServerRequestPart
    typealias OutboundOut = HTTPServerResponsePart

    func channelRead(context: ChannelHandlerContext, data: NIOAny) {
        let reqPart = self.unwrapInboundIn(data)

        switch reqPart {
        case .head(let head):
            let responseHead = HTTPResponseHead(version: head.version, status: .ok)
            let responseBody = HTTPServerResponsePart.body(.byteBuffer(ByteBufferAllocator().buffer(string: "Hello, World!")))
