func createMacrosSource(macrosToWrite: [(macro: Disassembler.MutableConfiguration.Macro, arguments: [Int: String], rawArguments: [Int: String])]) -> Source.FileDescription? {
    guard !macrosToWrite.isEmpty else {
        return nil
    }

    var sourceContent = ""
    for macroInfo in macrosToWrite {
        let macroName = macroInfo.macro.name
        let arguments = macroInfo.arguments
        if arguments.isEmpty {
            sourceContent += "macro \(macroName)\n"
        } else {
            let argumentList = arguments.map { "\($0.value): \(macroInfo.macro.datatypes[$0.key]!.rawValue)" }.joined(separator: ", ")
            sourceContent += "macro \(macroName)(\(argumentList))\n"
        }
    }

    let fileDescription = Source.FileDescription(content: sourceContent, metadata: ["author": "Your Name"])
    return fileDescription
}

