import SystemConfiguration

func isNetworkReachable() -> Bool {
    var flags: SCNetworkReachabilityFlags = []

    // Create a network reachability reference for the specified host (in this case, "www.apple.com")
    guard let defaultRouteReachability = SCNetworkReachabilityCreateWithName(nil, "www.apple.com") else {
        return false
    }

    // Retrieve the current reachability flags for the network reachability reference
    guard SCNetworkReachabilityGetFlags(defaultRouteReachability, &flags) else {
        return false
    }

    // Check if the device is reachable and if a connection is required
    let isReachable = flags.contains(.reachable)
    let needsConnection = flags.contains(.connectionRequired)

    // Return true if the device is reachable and does not require a connection
    return isReachable && !needsConnection
}

