class DependencyContainer {
    private var dependencies: [String: () -> Any] = [:]

    func register<T>(_ type: T.Type, _ dependency: @escaping () -> T) {
        let key = String(describing: type)
        dependencies[key] = dependency
    }

    func resolve<T>(_ type: T.Type) throws -> T {
        let key = String(describing: type)
        guard let dependency = dependencies[key] else {
            throw DependencyError.dependencyNotRegistered
        }
        guard let resolvedDependency = dependency() as? T else {
            throw DependencyError.invalidDependencyType
        }
        return resolvedDependency
    }
}

