func reverseStack<T>(_ stack: Stack<T>) -> Stack<T> {
    let reversedStack = Stack<T>()
    var tempStack = Stack<T>()

    while !stack.isEmpty() {
        if let element = stack.pop() {
            tempStack.push(element)
        }
