enum AppState {
    case foreground
    case active
    case terminate
}

class TaskScheduler {
    var tasks: [AppState: [() -> Void]] = [:]

    func scheduleTask(_ task: @escaping () -> Void, when state: AppState) {
        if tasks[state] == nil {
            tasks[state] = [task]
        } else {
            tasks[state]?.append(task)
        }
    }

    func handleStateChange(_ state: AppState) {
        if let tasksToExecute = tasks[state] {
            for task in tasksToExecute {
                task()
            }
        }
    }

    func applicationWillEnterForeground(_ application: UIApplication) {
        handleStateChange(.foreground)
    }

    func applicationDidBecomeActive(_ application: UIApplication) {
        handleStateChange(.active)
    }

    func applicationWillTerminate(_ application: UIApplication) {
        handleStateChange(.terminate)
    }
}

