import Combine

struct Driver<Value> {
    let publisher: AnyPublisher<Value, Never>
}

struct Signal<Value> {
    let publisher: AnyPublisher<Value, Never>
}

func system<State, Event>(
    initialState: State,
    reduce: @escaping (State, Event) -> State,
    feedback: Feedback<State, Event>...
) -> Driver<State> {
    let input = PassthroughSubject<Event, Never>()

    let feedbackSignals = feedback.map { feedback in
        feedback.run(Driver(publisher: input.eraseToAnyPublisher()))
    }

    let mergedFeedback = Publishers.MergeMany(feedbackSignals.map { $0.publisher }).eraseToAnyPublisher()

    let state = input.scan(initialState, reduce).merge(with: mergedFeedback.scan(initialState, reduce))

    return Driver(publisher: state.eraseToAnyPublisher())
}

