func sortPackages(_ packages: [[String: Any]]) -> [String] {
    var dependencyMap: [String: Set<String>] = [:]
    var packageSet: Set<String> = Set()

    for package in packages {
        if let name = package["name"] as? String, let dependencies = package["dependencies"] as? [String] {
            dependencyMap[name] = Set(dependencies)
            packageSet.insert(name)
            for dependency in dependencies {
                packageSet.insert(dependency)
            }
        }
    }

    var sortedPackages: [String] = []

    while !packageSet.isEmpty {
        var hasDependency: Set<String> = []
        for (package, dependencies) in dependencyMap {
            if dependencies.isSubset(of: packageSet) {
                sortedPackages.append(package)
                hasDependency.insert(package)
            }
        }
        packageSet.subtract(hasDependency)
        for (_, dependencies) in dependencyMap {
            dependencies.subtract(hasDependency)
        }
    }

    return sortedPackages
