func extractViewControllerTitles(fileContent: String, superclassName: String) -> [String] {
    var viewControllerTitles: [String] = []

    let lines = fileContent.components(separatedBy: .newlines)
    var currentViewController: String?

    for line in lines {
        if line.contains("class") {
            if let className = line.components(separatedBy: ":").first?.trimmingCharacters(in: .whitespaces) {
                currentViewController = className
            }
        } else if line.contains(": \(superclassName)") {
            if let viewController = currentViewController {
                viewControllerTitles.append(viewController)
            }
        }
    }

