func resolveDependencies(configuration: [(name: String, dependencies: [String], isTestTarget: Bool)]) -> [String: [String]] {
    var dependencyMap: [String: [String]] = [:]

    for target in configuration {
        dependencyMap[target.name] = target.dependencies
    }

    var resolvedDependencies: [String: [String]] = [:]

    func resolve(target: String, visited: Set<String>) -> [String] {
        var dependencies: [String] = []

        for dependency in dependencyMap[target] ?? [] {
            if visited.contains(dependency) {
                // Circular dependency detected
                // Handle the error or return an empty array based on the requirements
                return []
            }

            let newVisited = visited.union([dependency])
            let resolved = resolve(target: dependency, visited: newVisited)
            dependencies.append(contentsOf: resolved)
        }

        resolvedDependencies[target] = dependencies
        return dependencies
    }

    for target in configuration {
        if !target.isTestTarget {
            _ = resolve(target: target.name, visited: Set())
        }
    }

    return resolvedDependencies
}

