    }

    func getDirectionToTarget(targetDirection: Double) -> String {
        var minDiff = 180.0
        var closestLandmark = ""

        for (name, direction) in landmarks {
            let diff = abs(targetDirection - direction)
            if diff < minDiff {
                minDiff = diff
                closestLandmark = name
            }
        }

        let relativeDirection = (landmarks[closestLandmark]! - targetDirection + 360.0).truncatingRemainder(dividingBy: 360.0)

        if relativeDirection < 90.0 {
            return "Right"
        } else if relativeDirection > 270.0 {
            return "Left"
        } else {
            return "Straight"
        }
    }
}

