public func dynamicThrottle(with semaphore: DispatchSemaphore, delay: CFTimeInterval = 0.01, finalExecutionTimeout: CFTimeInterval = 0.5, block: @escaping () -> Void) {
    // Wait for the semaphore to have a value of 1, indicating that the previous block has finished executing
    semaphore.wait()

    // Schedule the block for execution after the specified delay
    DispatchQueue.global().asyncAfter(deadline: .now() + delay) {
        // Execute the block
        block()

        // Signal the semaphore to release, allowing the next block to be scheduled for execution
        semaphore.signal()
    }

    // Schedule a final execution timeout
    DispatchQueue.global().asyncAfter(deadline: .now() + finalExecutionTimeout) {
        // If the semaphore is still locked after the final execution timeout, release it to prevent deadlock
        if semaphore.wait(timeout: .now()) == .timedOut {
            semaphore.signal()
        }
    }
}

