        if let error = error as NSError?, error.domain == NSURLErrorDomain {
            if error.code == NSURLErrorNotConnectedToInternet {
                completion(.failure(.domainError))
            } else {
                completion(.failure(.responseError))
            }
            return
        }

        if let data = data {
            completion(.success(data))
        } else {
            completion(.failure(.responseError))
        }
    }
    task.resume()
}

