class EventsBus {
    var subscriptions: [String: [(Any, (String, [String: Any]) -> Void)]] = [:]

    func subscribe(_ object: Any, _ closure: @escaping (String, [String: Any]) -> Void, toEvent event: String) {
        if subscriptions[event] == nil {
            subscriptions[event] = []
        }
        subscriptions[event]?.append((object, closure))
    }

    func unsubscribe(_ object: Any) {
        for (event, _) in subscriptions {
            subscriptions[event]?.removeAll { $0.0 as AnyObject === object as AnyObject }
