    guard numbers.count > 2 else { return 0.0 }

    var sum = 0
    var minVal = Int.max
    var maxVal = Int.min

    for num in numbers {
        sum += num
        if num < minVal {
            minVal = num
        }
        if num > maxVal {
            maxVal = num
        }
    }

