public class Trie<ElementType: Collection> where ElementType.Element: Hashable {

  public typealias Node = TrieNode<ElementType.Element>
  public let root: Node

  public init() {
    root = Node()
  }

  public func insert(_ word: ElementType) {
    var current = root
    for element in word {
      if let child = current.children[element] {
        current = child
      } else {
        let newNode = Node()
        newNode.key = element
        newNode.parent = current
        current.children[element] = newNode
        current = newNode
      }
    }
    current.isTerminating = true
  }

  public func search(_ word: ElementType) -> Bool {
    var current = root
    for element in word {
      guard let child = current.children[element] else {
        return false
      }
      current = child
    }
    return current.isTerminating
  }

  public func startsWith(_ prefix: ElementType) -> Bool {
    var current = root
    for element in prefix {
      guard let child = current.children[element] else {
        return false
      }
      current = child
    }
    return true
  }
}

