func parsePackageManifest(_ packageSwiftContent: String) -> [String: [String]] {
    var libraryTargets: [String: [String]] = [:]

    // Extracting products section from the package.swift content
    if let productsRange = packageSwiftContent.range(of: "products: [") {
        let productsSubstring = packageSwiftContent[productsRange.lowerBound...]
        if let productsEndIndex = productsSubstring.range(of: "]")?.lowerBound {
            let productsContent = productsSubstring[..<productsEndIndex]

            // Extracting library names and their corresponding targets
            let libraryRegex = try! NSRegularExpression(pattern: "\\.library\\(name: \"(\\w+)\",\\s+targets: \\[(.*?)\\]\\)", options: [])
            let matches = libraryRegex.matches(in: String(productsContent), options: [], range: NSRange(location: 0, length: productsContent.count))

            for match in matches {
                if let libraryRange = Range(match.range(at: 1), in: String(productsContent)),
                   let targetsRange = Range(match.range(at: 2), in: String(productsContent)) {
                    let libraryName = String(productsContent[libraryRange])
                    let targetsString = String(productsContent[targetsRange])
                    let targets = targetsString.components(separatedBy: ", ")
                    libraryTargets[libraryName] = targets
                }
            }
        }
    }

    return libraryTargets
}

