func base58Encode(_ data: [UInt8]) -> String {
    let alphabet = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"
    let base = BigInt(58)
    var x = BigInt(data)
    var result = ""

    while x > 0 {
        let (quotient, remainder) = x.quotientAndRemainder(dividingBy: base)
        result = String(alphabet[String.Index(encodedOffset: Int(remainder))] ) + result
        x = quotient
    }

    for byte in data {
        if byte != 0 {
            break
        }
        result = "1" + result
    }

    return result
}

func base58Decode(_ data: String) -> [UInt8]? {
    let alphabet = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"
    let base = BigInt(58)
    var result = BigInt(0)

    for char in data {
        guard let index = alphabet.firstIndex(of: char) else { return nil }
        result *= base
        result += BigInt(alphabet.distance(from: alphabet.startIndex, to: index))
    }

    var bytes = [UInt8]()
    while result > 0 {
        let (quotient, remainder) = result.quotientAndRemainder(dividingBy: 256)
        bytes.insert(UInt8(remainder), at: 0)
        result = quotient
    }

    return bytes
}

