import XCTest

class CustomAnimation {
    var view: UIView
    var duration: TimeInterval

    init(view: UIView, duration: TimeInterval) {
        self.view = view
        self.duration = duration
    }

    func animatePosition(to newPosition: CGPoint, completion: @escaping () -> Void) {
        UIView.animate(withDuration: duration, animations: {
            self.view.frame.origin = newPosition
        }, completion: { _ in
            completion()
        })
    }

    func animateScale(to newScale: CGFloat, completion: @escaping () -> Void) {
        UIView.animate(withDuration: duration, animations: {
            self.view.transform = CGAffineTransform(scaleX: newScale, y: newScale)
        }, completion: { _ in
            completion()
        })
    }

    func animateOpacity(to newOpacity: CGFloat, completion: @escaping () -> Void) {
        UIView.animate(withDuration: duration, animations: {
            self.view.alpha = newOpacity
        }, completion: { _ in
            completion()
        })
    }
}

class CustomAnimationTests: XCTestCase {
    var view: UIView!
    var customAnimation: CustomAnimation!

    override func setUp() {
        super.setUp()
