```
The program should output:
```
@discardableResult: 1
@objc: 1
@available: 1
```

Write a program that takes a Swift source file as input and outputs the count of each unique Swift declaration attribute kind found in the file.

code:
import Foundation

func countSwiftDeclarationAttributes(in sourceFile: String) -> [String: Int] {
    var attributeCounts: [String: Int] = [:]

    guard let fileContent = try? String(contentsOfFile: sourceFile) else {
        print("Error: Unable to read the file.")
        return attributeCounts
    }

    let attributePattern = #"@(\w+)"#
    let regex = try! NSRegularExpression(pattern: attributePattern, options: [])

    let matches = regex.matches(in: fileContent, options: [], range: NSRange(location: 0, length: fileContent.utf16.count))

    for match in matches {
        if let range = Range(match.range(at: 1), in: fileContent) {
            let attribute = String(fileContent[range])
            attributeCounts[attribute, default: 0] += 1
        }
    }

    return attributeCounts
}

