import CoreGraphics

func calculateBezierCurveLength(segments: [Segment]) -> CGFloat {
    var totalLength: CGFloat = 0.0

    for segment in segments {
        let lineLength = sqrt(pow(segment.curve.x - segment.line.x, 2) + pow(segment.curve.y - segment.line.y, 2))
        let curveLength = sqrt(pow(segment.curve.x - segment.control.x, 2) + pow(segment.curve.y - segment.control.y, 2))
        totalLength += lineLength + curveLength
    }

    return totalLength
}

