func fetchAccountInfo(from url: URL, completionHandler: @escaping (Result<Bank, Error>) -> Void) {
    let task = URLSession.shared.dataTask(with: url) { data, response, error in
        if let error = error {
            completionHandler(.failure(error))
            return
        }

        guard let data = data else {
            let dataError = NSError(domain: "com.yourapp", code: 0, userInfo: [NSLocalizedDescriptionKey: "No data received"])
            completionHandler(.failure(dataError))
            return
        }

        do {
            let response = try JSONDecoder().decode(Bank.self, from: data)
            completionHandler(.success(response))
        } catch let decodingError {
            completionHandler(.failure(decodingError))
        }
    }
    task.resume()
}

