func sortDictionary(dictionary: [String: String]) -> [String: String] {
    // Sort the keys in ascending order
    let sortedKeys = Array(dictionary.keys).sorted()

    // Sort the keys in reverse alphabetical order if their values are the same
    let sortedKeysWithDuplicates = sortedKeys.sorted { key1, key2 in
        let value1 = dictionary[key1]!
        let value2 = dictionary[key2]!

        if value1 == value2 {
            return key1 > key2
        } else {
            return value1 < value2
        }
    }

    // Create a new dictionary with the sorted key-value pairs
    var sortedDictionary: [String: String] = [:]
    for key in sortedKeysWithDuplicates {
        sortedDictionary[key] = dictionary[key]
    }

    return sortedDictionary
}

func generateDistinctPrimesInRange(min: Int, max: Int, count: Int, skip: [Int]) -> [Int] {
    // Create an array to store the distinct prime numbers
    var primes: [Int] = []

    // Iterate through the range from min to max (inclusive)
    for num in min...max {
        // Check if the number is in the skip array
        if skip.contains(num) {
            continue
        }

        // Check if the number is prime
        if isPrime(num) {
            // Check if the number is already in the primes array
            if primes.contains(num) {
                continue
            }

            // Add the prime number to the primes array
            primes.append(num)

            // Check if we have generated enough distinct prime numbers
            if primes.count == count {
                return primes
            }
        }
    }

    // If we couldn't generate enough distinct prime numbers, return an empty array
    return []
}

