    private static let codexPermissionEvidenceChunkBytes = 64 * 1024

    private func codexLaunchHasExplicitPermissions(_ launchCommand: AgentHookLaunchCommandRecord?) -> Bool {
        guard let launchCommand,
              AgentLaunchCaptureTrust.launcherDescribesKind(launchCommand.launcher, kind: "codex") else {
            return false
        }
        let arguments = launchCommand.arguments
        for (index, argument) in arguments.enumerated() {
            if [
                "--yolo",
                "--full-auto",
                "--dangerously-bypass-approvals-and-sandbox",
                "-a",
                "--ask-for-approval",
                "-s",
                "--sandbox",
            ].contains(argument) {
                return true
            }
            if argument.hasPrefix("--ask-for-approval=") || argument.hasPrefix("--sandbox=") {
                return true
            }
            if argument == "-c" || argument == "--config",
               index + 1 < arguments.count,
               codexConfigOverridesPermissions(arguments[index + 1]) {
                return true
            }
            if argument.hasPrefix("-c=") || argument.hasPrefix("--config=") {
                let components = argument.split(
                    separator: "=",
                    maxSplits: 1,
                    omittingEmptySubsequences: false
                )
                if components.count == 2,
                   codexConfigOverridesPermissions(String(components[1])) {
                    return true
                }
            }
        }
        return false
    }

    private func codexConfigOverridesPermissions(_ value: String) -> Bool {
        let key = value.split(separator: "=", maxSplits: 1).first?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return key == "approval_policy" || key == "sandbox_mode"
    }
    func agentHookSessionHasDurableResumeEvidence(
        kind: String,
        launchCommand: AgentHookLaunchCommandRecord?
    ) -> Bool {
        guard normalizedHookValue(launchCommand?.source)?.lowercased() != "rejected" else { return false }
        guard kind == "codex" else { return true }
        guard let launchCommand else { return true }
        if normalizedHookValue(launchCommand.environment?["CODEX_HOME"]) != nil {
            return true
        }
        if normalizedHookValue(launchCommand.source)?.lowercased() == "default" { return true }
        guard !launchCommand.arguments.isEmpty else { return false }
        let source = normalizedHookValue(launchCommand.source)?.lowercased()
        if source == "environment", codexLaunchEnvironmentIsWeak(launchCommand.environment) {
            return false
        }
        switch source {
        case nil, "environment", "process":
            return true
        default:
            return false
        }
    }

    func preferredAgentHookResumeLaunchCommand(
        kind: String,
        current: AgentHookLaunchCommandRecord?,
        mapped: ClaudeHookSessionRecord?,
        transcriptPath: String? = nil,
        currentPID: Int? = nil
    ) -> AgentHookLaunchCommandRecord? {
        if normalizedHookValue(current?.source)?.lowercased() == "rejected" {
            return current
        }
        if kind == "codex",
           let currentPID,
           currentPID == mapped?.pid,
           !codexLaunchHasExplicitPermissions(current),
           codexLaunchHasExplicitPermissions(mapped?.launchCommand) {
            return mapped?.launchCommand
        }
        let selected: AgentHookLaunchCommandRecord? = {
            let currentSource = normalizedHookValue(current?.source)?.lowercased()
            if let current,
               currentSource != "default",
               agentHookSessionHasDurableResumeEvidence(kind: kind, launchCommand: current) {
                return current
            }
            if let mappedLaunchCommand = mapped?.launchCommand,
               agentHookSessionHasDurableResumeEvidence(kind: kind, launchCommand: mappedLaunchCommand) {
                return mappedLaunchCommand
            }
            if let current = replaySafeCodexLaunchCommand(kind: kind, launchCommand: current) {
                return current
            }
            if agentHookMappedSessionHasDurableTargetEvidence(kind: kind, mapped: mapped),
               let mapped = replaySafeCodexLaunchCommand(kind: kind, launchCommand: mapped?.launchCommand) {
                return mapped
            }
            if let current,
               currentSource == "default",
               agentHookSessionHasDurableResumeEvidence(kind: kind, launchCommand: current) {
                return current
            }
            if agentHookMappedSessionHasDurableTargetEvidence(kind: kind, mapped: mapped) {
                return nil
            }
            return current ?? mapped?.launchCommand
        }()
        guard kind == "codex" else { return selected }
        return repairedCodexLaunchCommand(
            selected,
            transcriptPath: transcriptPath
        )
    }

    func preferredAgentHookResumeWorkingDirectory(
        kind: String,
        current: AgentHookLaunchCommandRecord?,
        currentCwd: String?,
        mapped: ClaudeHookSessionRecord?
    ) -> String? {
        if normalizedHookValue(current?.source)?.lowercased() == "rejected" {
            return currentCwd ?? mapped?.cwd
        }
        let currentSource = normalizedHookValue(current?.source)?.lowercased()
        if let current, currentSource != "default", agentHookSessionHasDurableResumeEvidence(kind: kind, launchCommand: current) {
            return currentCwd ?? mapped?.cwd
        }
        if let launchCommand = mapped?.launchCommand,
           agentHookSessionHasDurableResumeEvidence(kind: kind, launchCommand: launchCommand) {
            return mapped?.cwd ?? currentCwd
        }
        if agentHookMappedSessionHasDurableTargetEvidence(kind: kind, mapped: mapped) {
            return mapped?.cwd ?? currentCwd
        }
        return currentCwd ?? mapped?.cwd
    }

    func agentHookMappedSessionHasDurableTargetEvidence(
        kind: String,
        mapped: ClaudeHookSessionRecord?
    ) -> Bool {
        guard let mapped else { return false }
        guard normalizedHookValue(mapped.launchCommand?.source)?.lowercased() != "rejected" else { return false }
        guard kind == "codex" else { return true }
        if mapped.isRestorable == true { return true }
        if let transcriptPath = normalizedHookValue(mapped.transcriptPath),
           FileManager.default.fileExists(atPath: (transcriptPath as NSString).expandingTildeInPath) {
            return true
        }
        guard let launchCommand = mapped.launchCommand else { return false }
        if normalizedHookValue(launchCommand.environment?["CODEX_HOME"]) != nil { return true }
        if normalizedHookValue(launchCommand.source)?.lowercased() == "default" { return true }
        guard !launchCommand.arguments.isEmpty else { return false }
        let source = normalizedHookValue(launchCommand.source)?.lowercased()
        if source == "environment", codexLaunchEnvironmentIsWeak(launchCommand.environment) {
            return false
        }
        switch source {
        case nil, "environment", "process":
            return true
        default:
            return false
        }
    }

    private func codexLaunchEnvironmentIsWeak(_ environment: [String: String]?) -> Bool {
        normalizedHookValue(environment?["CODEX_HOME"]) == nil
            && (normalizedHookValue(environment?["ANTHROPIC_BASE_URL"]) != nil
                || normalizedHookValue(environment?["CLAUDE_CONFIG_DIR"]) != nil)
    }

    /// A same-kind launch capture can inherit Claude account-selection environment from the
    /// terminal without making its sanitized Codex flags unsafe to replay. Keep those flags while
    /// dropping

private func appendAgentJournalDeadLetter(draft: AgentJournalEventDraft, message: String) {
        let url = Self.agentJournalDeadLetterURL()
        let maximumBytes: UInt64 = 1_048_576
        let fileManager = FileManager.default
        do {
            try fileManager.createDirectory(
                at: url.deletingLastPathComponent(),
                withIntermediateDirectories: true
            )
            if let size = (try? fileManager.attributesOfItem(atPath: url.path)[.size]) as? UInt64,
               size > maximumBytes {
                try? fileManager.removeItem(at: url)
            }
            var record: [String: Any] = [
                "at_ms": Int64(Date().timeIntervalSince1970 * 1000),
                "error": message,
            ]
            if let draftData = try? JSONEncoder().encode(draft),
               let draftObject = try? JSONSerialization.jsonObject(with: draftData) {
                record["event"] = draftObject
            }
            let lineData = try JSONSerialization.data(withJSONObject: record)

import CmuxAgentJournal
import Foundation

extension CMUXCLI {
    /// Emits one semantic agent event into the app's append-only agent
    /// journal and blocks until the app acknowledges the durable commit.
    ///
    /// This is the structured replacement for the fire-and-forget
    /// `set_agent_lifecycle` verb: sidebar lifecycle is now a reduction over
    /// these events. Attribution is decided by the caller — an event that
    /// could not be attributed carries `unattributedReason` (and no target)
    /// so the app surfaces it as a diagnostic instead of guessing a pane.
    ///
    /// Delivery failures are never silent: they land in the dead-letter file
    /// and, when a session store and telemetry are provided, in the throttled
    /// hook-failure report channel.
    func emitAgentJournalEvent(
        client: SocketClient,
        kind: AgentJournalEventKind,
        source: String,
        agentKey: String,
        sessionId: String?,
        workspaceId: String?,
        surfaceId: String?,
        unattributedReason: String? = nil,
        isSubagent: Bool = false,
        pendingWork: Bool = false,
        nativeEvent: String?,
        declaredPhase: AgentLifecyclePhase? = nil,
        detail: String? = nil,
        store: ClaudeHookSessionStore? = nil,
        telemetry: CLISocketSentryTelemetry? = nil
    ) {
        // A malformed or partial target (empty string, non-UUID, missing
        // half) is never trusted: the event is journaled as an explicit
        // diagnostic instead of being rejected at admission or guessed.
        let validWorkspaceId = workspaceId.flatMap { UUID(uuidString: $0) != nil ? $0 : nil }
        let validSurfaceId = surfaceId.flatMap { UUID(uuidString: $0) != nil ? $0 : nil }
        let hasCompleteTarget = validWorkspaceId != nil && validSurfaceId != nil
        let resolvedReason: String?
        if let unattributedReason {
            resolvedReason = unattributedReason
        } else if !hasCompleteTarget {
            resolvedReason = "malformed-target"
        } else {
            resolvedReason = nil
        }
        let draft = AgentJournalEventDraft(
            kind: kind,
            occurredAtMs: Int64(Date().timeIntervalSince1970 * 1000),
            source: source,
            agentKey: agentKey,
            sessionId: sessionId,
            workspaceId: resolvedReason == nil ? validWorkspaceId : nil,
            surfaceId: resolvedReason == nil ? validSurfaceId : nil,
            unattributedReason: resolvedReason,
            isSubagent: isSubagent,
            pendingWork: pendingWork,
            nativeEvent: nativeEvent,
            declaredPhase: declaredPhase,
            detail: detail
        )
        if let problem = draft.validationProblem() {
            recordAgentJournalDeliveryFailure(
                draft: draft,
                message: "invalid draft: \(problem)",
                store: store,
                telemetry: telemetry
            )
            return
        }
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys, .withoutEscapingSlashes]
        guard let data = try? encoder.encode(draft),
              let json = String(data: data, encoding: .utf8) else {
            recordAgentJournalDeliveryFailure(
                draft: draft,
                message: "encode failed",
                store: store,
                telemetry: telemetry
            )
            return
        }
        do {
            let response = try sendV1Command("agent_journal_append \(json)", client: client)
            guard response.hasPrefix("OK") else {
                recordAgentJournalDeliveryFailure(
                    draft: draft,
                    message: response,
                    store: store,
                    telemetry: telemetry
                )
                return
            }
        } catch {
            recordAgentJournalDeliveryFailure(
                draft: draft,
                message: String(describing: error),
                store: store,
                telemetry: telemetry
            )
        }
    }

    /// Resolves the semantic kind for a generic agent hook's `notification`
    /// action: the native event name maps first (`StopFailure`,
    /// `pre_approval_request`, …); only when the mapper has nothing stronger
    /// than an observation does the prose classifier's verdict fill in, as a
    /// last-resort adapter detail.
    func agentJournalNotificationKind(
        def: AgentHookDef,
        nativeEvent: String?,
        toolName: String?,
        summary: AgentHookNotificationSummary
    ) -> AgentJournalEventKind {
        let mapper = AgentSemanticEventMapper()
        if let nativeEvent, !nativeEvent.isEmpty {
            let mapped = mapper.kind(source: def.name, nativeEvent: nativeEvent, toolName: toolName)
            if mapped != .stateChanged {
                return mapped
            }
        }
        switch summary.status {
        case .needsInput?:
            return summary.notifyCategory == .needsPermission ? .approvalRequested : .questionRequested
        case .error?:
            return .errorReported
        case .idle?:
            return .turnCompleted
        case nil:
            return .stateChanged
        }
    }

    /// Records a failed journal emission: appended to the bounded dead-letter
    /// file, warned on stderr, and (when possible) reported through the
    /// throttled hook-failure channel. Never silent.
    func recordAgentJournalDeliveryFailure(
        draft: AgentJournalEventDraft,
        message: String,
        store: ClaudeHookSessionStore?,
        telemetry: CLISocketSentryTelemetry?
    ) {
        appendAgentJournalDeadLetter(draft: draft, message: message)
        cliWriteStderr("Warning: agent journal append failed (\(draft.kind.rawValue)): \(message)\n")
        if let store, let telemetry {
            reportAgentHookFailure(
                stage: .journalAppend,
                agentName: draft.source,
                sessionId: draft.sessionId ?? "",
                event: draft.nativeEvent ?? draft.kind.rawValue,
                error: nil,
                store: store,
                telemetry: telemetry
            )
        }
    }

    /// Dead-letter location: one JSON line per failed emission, bounded by
    /// truncation so an unreachable app cannot grow it without limit.
    static func agentJournalDeadLetterURL(env: [String: String] = ProcessInfo.processInfo.environment) -> URL {
        if let override = env["CMUX_AGENT_JOURNAL_DEAD_LETTER_PATH"], !override.isEmpty {
            return URL(fileURLWithPath: override)
        }
        let home = FileManager.default.homeDirectoryForCurrentUser
        return home
            .appendingPathComponent(".cmuxterm", isDirectory: true)
            .appendingPathComponent("agent-journal-dead-letter.jsonl", isDirectory: false)
    }

    private func appendAgentJournalDeadLetter(draft: AgentJournalEventDraft, message: String) {
        let url = Self.agentJournalDeadLetterURL()
        let maximumBytes: UInt64 = 1_048_576
        let fileManager = FileManager.default
        do {
            try fileManager.createDirectory(
                at: url.deletingLastPathComponent(),
                withIntermediateDirectories: true
            )
            if let size = (try? fileManager.attributesOfItem(atPath: url.path)[.size]) as? UInt64,
               size > maximumBytes {
                try? fileManager.removeItem(at: url)
            }
            var record: [String: Any] = [
                "at_ms": Int64(Date().timeIntervalSince1970 * 1000),
                "error": message,
            ]
            if let draftData = try? JSONEncoder().encode(draft),
               let draftObject = try? JSONSerialization.jsonObject(with: draftData) {
                record["event"] = draftObject
            }
            let lineData = try JSONSerialization.data(withJSONObject: record)

