    func uniqueCallerWorkspaceIdForClaudeHook(
        callerTerminalBinding: (() -> CallerTerminalBinding?)?,
        client: SocketClient
    ) -> String? {
        if let callerTerminalBinding {
            guard let binding = callerTerminalBinding(),
